def exact_match(predictions, references):
    if len(predictions) != len(references) or not references:
        raise ValueError("Inputs must have equal, non-zero lengths")
    matches = sum(p.strip() == r.strip() for p, r in zip(predictions, references))
    return matches / len(references)

predictions = ["Paris", "4", "blue"]
references = ["Paris", "4", "green"]
print(f"Exact match: {exact_match(predictions, references):.1%}")
